function authorFor(copy: GuideCopy): [LocalizedAuthor, LocalizedAuthor] {
  return [
    { id: `powerbasefit-bar-team-${copy.locale}`, name: "PowerBaseFit", kind: "Organization", role: copy.eyebrow.replace(/^PowerBaseFit · /u, "") },
    { id: `powerbasefit-bar-review-${copy.locale}`, name: "PowerBaseFit", kind: "Organization", role: copy.headings.inspect }
  ];
}

function imagesFor(copy: GuideCopy): LocalizedImage[] {
  return imageFiles.map(([src, width, height], index) => ({
    id: `commercial-olympic-bar-image-${index + 1}`,
    src,
    width,
    height,
    alt: copy.imageCopy[index][0],
    caption: copy.imageCopy[index][1]
  }));
}

function rich(id: string, heading: string, paragraphs: string[], component?: string): ContentBlock {
  return { id, type: "rich_text", heading, content: paragraphs.join("\n\n"), data: component ? { component } : undefined };
}

function bodyFor(copy: GuideCopy): ContentBlock[] {
  const useMarkdown = copy.useOptions.map(([heading, text]) => `### ${heading}\n\n${text}`).join("\n\n");
  return [
    rich("quick-answer", copy.headings.answer, copy.answer, "quick-answer"),
    rich("olympic-bar-definition", copy.headings.definition, copy.definition, "definition"),
    { id: "training-zone-selection", type: "custom", heading: copy.headings.use, data: { component: "markdown-section", markdown: useMarkdown } },
    { id: "buyer-specification-table", type: "specifications", heading: copy.headings.table, data: { columns: copy.tableColumns, rows: copy.tableRows } },
    rich("sleeve-rotation", copy.headings.rotation, copy.rotation),
    rich("shaft-behaviour", copy.headings.shaft, copy.shaft),
    rich("knurl-and-marks", copy.headings.knurl, copy.knurl),
    rich("system-compatibility", copy.headings.fit, copy.fit),
    rich("finish-and-maintenance", copy.headings.finish, copy.finish),
    { id: "production-inspection", type: "features", heading: copy.headings.inspect, data: { items: copy.checklist } },
    rich("oem-private-label", copy.headings.oem, copy.oem),
    rich("sample-approval", copy.headings.sample, copy.sample),
    rich("bulk-packaging", copy.headings.pack, copy.pack),
    { id: "rfq-handoff", type: "custom", heading: copy.headings.rfq, data: { component: "markdown-section", markdown: copy.rfq.join("\n\n") } }
  ];
}

function linksFor(copy: GuideCopy) {
  if (copy.locale === "ar") {
    return [
      { targetContentId: "weight-plate-tolerance-bulk-order-guide", label: "دليل فحص أقراص الأثقال" },
      { targetContentId: "cable-attachment-compatibility-oem-guide", label: "دليل توافق ملحقات الكابل" }
    ];
  }
  return defaultTargets.map((targetContentId, index) => ({ targetContentId, label: copy.linkLabels[index] }));
}

function versionFor(copy: GuideCopy): LocalizedContentVersion {
  const [author, reviewer] = authorFor(copy);
  const segments = copy.path.split("/").filter(Boolean);
  return {
    locale: copy.locale,
    translationStatus: copy.locale === "en" ? "published" : "localized",
    reviewStatus: "approved",
    publishStatus: "published",
    slug: segments.at(-1) ?? entityId,
    publicPath: copy.path,
    title: copy.title,
    description: copy.description,
    h1: copy.h1,
    body: bodyFor(copy),
    faq: copy.faq.map(([question, answer], index) => ({ id: `faq-${index + 1}`, question, answer })),
    author,
    reviewedBy: reviewer,
    schemaData: {
      category: copy.intent,
      breadcrumbs: [
        { name: copy.home, path: copy.locale === "en" || copy.locale === "ar" ? "/" : `/${segments[0]}` },
        { name: copy.library, path: copy.locale === "en" || copy.locale === "ar" ? "/resources" : `/${segments.slice(0, 2).join("/")}` },
        { name: copy.h1, path: copy.path }
      ],
      extra: {
        primaryKeyword: copy.primaryKeyword,
        secondaryKeywords: copy.secondaryKeywords,
        targetBuyer: copy.targetBuyer,
        eyebrow: copy.eyebrow,
        contactPath: copy.contactPath,
        ctaTitle: copy.cta[0],
        ctaText: copy.cta[1],
        ctaLabel: copy.cta[2]
      }
    },
    images: imagesFor(copy),
    internalLinks: linksFor(copy),
    canonicalData: { mode: "self" },
    hreflangData: { include: true },
    publishedAt,
    updatedAt: publishedAt,
    version: 1
  };
}

function englishMarkdown() {
  const table = [
    `| ${english.tableColumns.join(" | ")} |`,
    `| ${english.tableColumns.map(() => "---").join(" | ")} |`,
    ...english.tableRows.map((row) => `| ${row.join(" | ")} |`)
  ].join("\n");
  const faq = english.faq.map(([question, answer]) => `### ${question}\n\n${answer}`).join("\n\n");
  return [
    `## ${english.headings.answer}\n\n${english.answer.join("\n\n")}`,
    `## ${english.headings.definition}\n\n${english.definition.join("\n\n")}`,
    `## ${english.headings.use}\n\n${english.useOptions.map(([heading, text]) => `### ${heading}\n\n${text}`).join("\n\n")}`,
    `## ${english.headings.table}\n\n${table}`,
    `## ${english.headings.rotation}\n\n${english.rotation.join("\n\n")}`,
    `## ${english.headings.shaft}\n\n${english.shaft.join("\n\n")}`,
    `## ${english.headings.knurl}\n\n${english.knurl.join("\n\n")}`,
    `## ${english.headings.fit}\n\n${english.fit.join("\n\n")}`,
    `## ${english.headings.finish}\n\n${english.finish.join("\n\n")}`,
    `## ${english.headings.inspect}\n\n${english.checklist.map((item) => `- ${item}`).join("\n")}`,
    `## ${english.headings.oem}\n\n${english.oem.join("\n\n")}`,
    `## ${english.headings.sample}\n\n${english.sample.join("\n\n")}`,
    `## ${english.headings.pack}\n\n${english.pack.join("\n\n")}`,
    `## ${english.headings.rfq}\n\n${english.rfq.join("\n\n")}`,
    `## Frequently Asked Questions\n\n${faq}`,
    `## ${english.cta[0]}\n\n${english.cta[1]} [${english.cta[2]}](/contact).`
  ].join("\n\n");
}

export const commercialOlympicBarbellEnglishPost = {
  entityId,
  publicPath: english.path,
  title: english.title,
  h1: english.h1,
  description: english.description,
  primaryKeyword: english.primaryKeyword,
  secondaryKeywords: english.secondaryKeywords,
  searchIntent: english.intent,
  content: englishMarkdown(),
  images: imagesFor(english),
  publishedAt,
  updatedAt: publishedAt
};

export function withCommercialOlympicBarbellGuide(manifest: ContentManifest): ContentManifest {
  if (manifest.entities.some((entity) => entity.id === entityId)) throw new Error(`Duplicate content entity: ${entityId}`);
  const entity: ContentEntity = {
    id: entityId,
    type: "blog",
    defaultLocale: "en",
    versions: Object.fromEntries(copies.map((copy) => [copy.locale, versionFor(copy)])) as ContentEntity["versions"]
  };
  return { ...manifest, entities: [...manifest.entities, entity] };
}
